import{_ as T,a0 as n,w as p,s as a,ao as o,I as l,x as e,a1 as r,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"MTTR 已死，CIRT 长存 | LCTT x X-CMD","titleTemplate":false,"description":"MTTR 已死，CIRT 长存 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"MTTR 已死，CIRT 长存 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"MTTR 已死，CIRT 长存 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190712 MTTR is dead, long live CIRT","title":"MTTR 已死，CIRT 长存","tag":"201907","desc":""},"relativePath":"201907/20190712 MTTR is dead, long live CIRT.md","filePath":"[post].md"}'),u={name:"201907/20190712 MTTR is dead, long live CIRT.md"};function m(d,t,f,R,C,g){const s=n("Link");return p(),a("div",null,[t[18]||(t[18]=o('<h1 id="mttr-已死-cirt-长存" tabindex="-1">MTTR 已死，CIRT 长存 <a class="header-anchor" href="#mttr-已死-cirt-长存" aria-label="Permalink to “MTTR 已死，CIRT 长存”">​</a></h1><blockquote><p>通过关注影响业务的事件，CIRT 是衡量运维绩效的更准确方法。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/metrics_lead-steps-measure.png?itok=DG7rFZPk" alt="Green graph of measurements" title="Green graph of measurements"></p><p>IT 运维圈子的玩法正在发生变化，这意味着过去的规则越来越不合理。机构需要适当环境中的准确的、可理解的、且可操作的指标，以衡量运维绩效并推动关键业务转型。</p><p>越多的客户使用现代工具，他们管理的事件类型的变化越多，将所有这些不同事件粉碎到一个桶中以计算平均解决时间来表示运维绩效的意义就越少，这就是 IT 一直以来在做的事情。</p><h3 id="历史与指标" tabindex="-1">历史与指标 <a class="header-anchor" href="#历史与指标" aria-label="Permalink to “历史与指标”">​</a></h3>',6)),l("p",null,[t[1]||(t[1]=e("历史表明，在分析信号以防止错误和误解时，背景信息是关键。例如，在 20 世纪 80 年代，瑞典建立了一个分析水听器信号的系统，以提醒他们在瑞典当地水域出现的俄罗斯潜艇。瑞典人使用了他们认为代表一类俄罗斯潜艇的声学特征 —— 但实际上是鲱鱼在遇到潜在捕食者时释放的",-1)),r(s,{href:"http://blogfishx.blogspot.com/2014/05/herring-fart-to-communicate.html"},{default:i(()=>[...t[0]||(t[0]=[e("气泡声",-1)])]),_:1}),t[2]||(t[2]=e("。这种对指标的误解加剧了各国之间的紧张关系，几乎导致了战争。",-1))]),t[19]||(t[19]=o('<p><img src="https://opensource.com/sites/default/files/uploads/fish.png" alt="Funny fish cartoon" title="Funny fish cartoon"></p><p><ruby>平均解决时间<rt>Mean Time To Resolve</rt></ruby>（MTTR）是运维经理用于获得实现目标洞察力的主要运维绩效指标。这是一项基于<ruby>系统可靠性工程<rt>systems reliability engineering</rt></ruby>的古老措施。MTTR 已被许多行业采用，包括制造、设施维护以及最近的 IT 运维，它代表了解决在特定时间段内创建的事件所需的平均时间。</p><p>MTTR 的计算方法是将所有事件（从事件创建时间到解决时间）所需的时间除以事件总数。</p><p><img src="https://opensource.com/sites/default/files/uploads/mttr.png" alt="MTTR formula" title="MTTR formula"></p><p>正如它所说的，MTTR 是 <strong>所有</strong> 事件的平均值。MTTR 将高紧急事件和低紧急事件混为一谈。它还会重复计算每个单独的、未分组的事件，并得出有效的解决时间。它包括了在相同上下文中手动解决和自动解决的事件。它将在创建了几天（或几个月）甚至完全被忽略的事件混合在一起。最后，MTTR 包括每个小的瞬态突发事件（在 120 秒内自动关闭的事件），这些突发事件要么是非问题噪音，要么已由机器快速解决。</p><p><img src="https://opensource.com/sites/default/files/uploads/incidents.png" alt="Variability in incident types" title="Variability in incident types"></p><p>MTTR 将所有事件（无论何种类型）抛入一个桶中，将它们全部混合在一起，并计算整个集合中的“平均”解决时间。这种过于简单化的方法导致运维执行方式的的噪音、错误和误导性指示。</p><h3 id="一种衡量绩效的新方法" tabindex="-1">一种衡量绩效的新方法 <a class="header-anchor" href="#一种衡量绩效的新方法" aria-label="Permalink to “一种衡量绩效的新方法”">​</a></h3><p><ruby>关键事件响应时间<rt>Critical Incident Response Time</rt></ruby>（CIRT）是评估运维绩效的一种更准确的新方法。PagerDuty 创立了 CIRT 的概念，但该方法可供所有人免费使用。</p><p>CIRT 通过使用以下技术剔除来自信号的噪声，其重点关注最有可能影响业务的事件：</p><ol><li>真正影响（或可能影响）业务的事件很少是低紧急事件，因此要排除所有低紧急事件。</li><li>真正影响业务的事件很少（如果有的话）可以无需人为干预而通过监控工具自动解决，因此要排除未由人工解决的事件。</li><li>在 120 秒内解决的短暂、爆发性和瞬态事件几乎不可能是真正影响业务的事件，因此要排除它们。</li><li>长时间未被注意、提交或忽略（未确认、未解决）的事件很少会对业务造成影响；排除它们。注意：此阈值可以是特定于客户的统计推导数字（例如，高于均值的两个标准差），以避免使用任意数字。</li><li>由单独警报产生的个别未分组事件并不代表较大的业务影响事件。因此，模拟具有非常保守的阈值（例如，两分钟）的事件分组以计算响应时间。</li></ol><p>应用这些假设对响应时间有什么影响？简而言之，效果非常非常大！</p><p>通过在关键的、影响业务的事件中关注运维绩效，解决时间分布变窄并极大地向左偏移，因为现在它处理类似类型的事件而不是所有事件。</p><p>由于 MTTR 计算的响应时间长得多、人为地偏差，因此它是运维绩效较差的一个指标。另一方面，CIRT 是一项有意的措施，专注于对业务最重要的事件。</p><p>与 CIRT 一起使用的另一个关键措施是确认和解决事故的百分比。这很重要，因为它验证 CIRT（或 MTTA / MTTR）是否值得利用。例如，如果 MTTR 结果很低，比如 10 分钟，那听起来不错，但如果只有 42％ 的事件得到解决，那么 MTTR 是可疑的。</p><p>总之，CIRT 和确认、解决事件的百分比形成了一组有价值的指标，可以让你更好地了解运营的执行情况。衡量绩效是提高绩效的第一步，因此这些新措施对于实现机构的可持续、可衡量的改进周期至关重要。</p><hr>',17)),l("p",null,[t[4]||(t[4]=e("via: ",-1)),r(s,{href:"https://opensource.com/article/19/7/measure-operational-performance"},{default:i(()=>[...t[3]||(t[3]=[e("https://opensource.com/article/19/7/measure-operational-performance",-1)])]),_:1})]),l("p",null,[t[9]||(t[9]=e("作者：",-1)),r(s,{href:"https://opensource.com/users/juliegund/users/kearnsjd/users/ophir"},{default:i(()=>[...t[5]||(t[5]=[e("Julie Gunderson",-1)])]),_:1}),t[10]||(t[10]=e(" 选题：",-1)),r(s,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[6]||(t[6]=[e("lujun9972",-1)])]),_:1}),t[11]||(t[11]=e(" 译者：",-1)),r(s,{href:"https://github.com/wxy"},{default:i(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1}),t[12]||(t[12]=e(" 校对：",-1)),r(s,{href:"https://github.com/wxy"},{default:i(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[15]||(t[15]=e("本文由 ",-1)),r(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原创编译，",-1)),r(s,{href:"https://linux.cn/"},{default:i(()=>[...t[14]||(t[14]=[e("Linux中国",-1)])]),_:1}),t[17]||(t[17]=e(" 荣誉推出",-1))])])}const y=T(u,[["render",m]]);export{b as __pageData,y as default};
